(def batch96-capture (future (let [instance (seon.cluster/start! {:seon.boot/cluster-name "old-world3" :seon.boot/root "/Users/sean/src/seon/tmp/cloned-base-root/data/clusters" :seon.config/manifest {:seon.config.ai/no-provider true}}) connection (:seon.boot/cluster-connection instance) reports (atom []) closed (promise) key :cloned-base/batch96 probe (fn [database] (seon.db/q '[:find ?closed . :in $ ?id :where [?turn :seon.turn/id ?id] [?turn :seon.turn/closed-tx ?closed]] database (seon.bootstrap/run-id "root")))] (datahike.api/listen connection key (fn [report] (swap! reports conj {:t (:max-tx (:db-after report)) :datoms (mapv (fn [d] [(:e d) (:a d) (:v d) (:tx d) (:added d)]) (:tx-data report))}) (when (probe (:db-after report)) (deliver closed true)))) (try (when (probe @connection) (deliver closed true)) (when-not (deref closed 120000 false) (throw (ex-info "Opening did not close" {}))) (let [basis (:max-tx @connection) result (seon.cluster/refresh-source! "/Users/sean/src/seon/tmp/cloned-base-root/data/clusters" ["src/seon/ai/tokens.cljc"]) evidence {:before basis :after (:max-tx @connection) :publication result :transactions (filterv #(> (:t %) basis) @reports)}] (spit "tmp/cloned-base-batch96-result.edn" (pr-str evidence)) evidence) (finally (datahike.api/unlisten connection key) (seon.cluster/stop! instance))))))
